<?php require '../includes/layout.php'; require_role(['admin']); $d=db();$q=trim($_GET['q']??'');$where='';$params=[];if($q){$where='WHERE l.action LIKE ? OR u.name LIKE ?';$params=["%$q%","%$q%"];}
$s=$d->prepare("SELECT l.*,u.name user_name FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id $where ORDER BY l.id DESC LIMIT 200");$s->execute($params);$logs=$s->fetchAll();head('Activity');?><div class="mb-4"><p class="text-xs font-semibold uppercase tracking-[.2em] text-mute">Audit trail</p><h1 class="text-2xl font-semibold mt-1">Activity log</h1><p class="text-sm text-mute mt-1">Review recent staff and administrator actions.</p></div>
<form method="get" class="<?=card('p-4 mb-5')?> flex gap-2"><input class="<?=INP?>" name="q" value="<?=e($q)?>" placeholder="Search action or user"><button class="<?=BTN?>">Search</button></form><div class="<?=card('overflow-x-auto')?>"><table class="w-full min-w-[38rem] text-sm"><thead><tr class="text-left text-xs uppercase tracking-wide text-mute"><th class="p-3">Date</th><th>User</th><th class="p-3">Action</th></tr></thead><tbody><?php foreach($logs as $log):?><tr class="border-t border-line"><td class="p-3"><?=date('M j, Y g:i A',strtotime($log['created_at']))?></td><td><?=e($log['user_name']?:'System/Guest')?></td><td class="p-3"><?=e($log['action'])?></td></tr><?php endforeach?><?php if(!$logs):?><tr><td class="p-8 text-center text-mute" colspan="3">No activity found.</td></tr><?php endif?></tbody></table></div><?php foot();
